def build() -> None:
    rows = []
    for (rid, page, group, metric, value, period, src, finding, note) in R:
        src_ids = [s for s in src.split("|") if s]
        for s in src_ids:
            if s not in SOURCES:
                raise SystemExit(f"unknown source id {s} in row {rid}")
        status = "verified" if value.strip() else "unverified"
        flag = ""
        if status == "unverified":
            flag = "U-" + rid
        rows.append({
            "id": rid, "page": page, "group": group, "metric": metric,
            "value": value, "period": period, "sources": src_ids,
            "finding": finding, "note": note, "status": status, "flag": flag,
        })
    ids = [r["id"] for r in rows]
    if len(ids) != len(set(ids)):
        dupes = sorted({i for i in ids if ids.count(i) > 1})
        raise SystemExit(f"duplicate row ids: {dupes}")

    sources = {
        k: {"publisher": v[0], "title": v[1], "url": v[2], "kind": v[3], "retrieved": RETRIEVED}
        for k, v in SOURCES.items()
    }
    irregularities = [
        {"id": i, "title": t, "detail": d, "links": links}
        for (i, t, d, links) in IRREGULARITIES
    ]
    (ROOT / "data").mkdir(exist_ok=True)
    (ROOT / "data/brief_rows.json").write_text(json.dumps({"retrieved": RETRIEVED, "rows": rows}, indent=2) + "\n", encoding="utf-8")
    (ROOT / "data/brief_sources.json").write_text(json.dumps({"retrieved": RETRIEVED, "sources": sources}, indent=2) + "\n", encoding="utf-8")
    (ROOT / "data/brief_flags.json").write_text(json.dumps({"retrieved": RETRIEVED, "irregularities": irregularities}, indent=2) + "\n", encoding="utf-8")
    verified = sum(1 for r in rows if r["status"] == "verified")
    print(f"rows={len(rows)} verified={verified} blank_flagged={len(rows)-verified} sources={len(sources)} irregularities={len(irregularities)}")


if __name__ == "__main__":
    build()
